introduction.c_program:
#include <stdio.h>

// Demonstrating primitive vs user-defined non-primitive structure
struct Student {
    int id;
    char name[50];
    float gpa;
};

int main(void) {
    // Primitive types
    int semester = 3;
    float creditHours = 18.5f;

    // User-defined composite data structure
    struct Student s1 = {101, "Alice Smith", 3.85f};

    printf("=== Data Structures: Primitive vs Non-Primitive ===\n");
    printf("Primitive: Semester = %d, Credits = %.1f\n", semester, creditHours);
    printf("Composite Struct: ID = %d, Name = %s, GPA = %.2f\n", s1.id, s1.name, s1.gpa);
    return 0;
}

