static_vs_dynamic_memory.c_program:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 5;
    // Allocate memory dynamically on Heap
    int *arr = (int *)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    for (int i = 0; i < n; i++) {
        arr[i] = (i + 1) * 10;
    }

    printf("Dynamically Allocated Array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Crucial: Deallocate to prevent memory leak
    free(arr);
    arr = NULL; // Prevent dangling pointer
    printf("Memory successfully freed.\n");
    return 0;
}

arrays_and_pointers.c_program:
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int val;
    struct Node *next;
};

int main(void) {
    int arr[] = {10, 20, 30};
    int *ptr = arr;

    printf("Pointer arithmetic on array:\n");
    for (int i = 0; i < 3; i++) {
        printf("*(ptr + %d) = %d at address %p\n", i, *(ptr + i), (void *)(ptr + i));
    }

    // Struct pointer and arrow operator
    struct Node n1 = {100, NULL};
    struct Node *nPtr = &n1;
    printf("Struct access via pointer: nPtr->val = %d\n", nPtr->val);
    return 0;
}
